        block_state_id state = mc_26_3_acacia_trapdoor_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:acacia_trapdoor: properties -> state mismatch");
        b8 ok = mc_26_3_acacia_trapdoor_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:acacia_trapdoor: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:acacia_trapdoor: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:acacia_trapdoor: reverse property mismatch: half");
        CHECK(actual.open == expected->properties.open, "minecraft:acacia_trapdoor: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:acacia_trapdoor: reverse property mismatch: powered");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:acacia_trapdoor: reverse property mismatch: waterlogged");
