static void test_bamboo_pressure_plate(void)
{
    const size_t count = sizeof(test_bamboo_pressure_plate_cases) / sizeof(test_bamboo_pressure_plate_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_bamboo_pressure_plate_case *expected = &test_bamboo_pressure_plate_cases[i];
        mc_26_3_bamboo_pressure_plate_properties actual = {0};
        block_state_id state = mc_26_3_bamboo_pressure_plate_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:bamboo_pressure_plate: properties -> state mismatch");
        b8 ok = mc_26_3_bamboo_pressure_plate_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:bamboo_pressure_plate: get_properties rejected valid state");
        CHECK(actual.powered == expected->properties.powered, "minecraft:bamboo_pressure_plate: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_bamboo_pressure_plate_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:bamboo_pressure_plate: get_state(NULL)");
    CHECK(mc_26_3_bamboo_pressure_plate_get_properties(0, NULL) == 0, "minecraft:bamboo_pressure_plate: get_properties(NULL)");
    CHECK(mc_26_3_bamboo_pressure_plate_get_properties(8548, &( mc_26_3_bamboo_pressure_plate_properties ){0}) == 0, "minecraft:bamboo_pressure_plate: accepted state below range");
    CHECK(mc_26_3_bamboo_pressure_plate_get_properties(8551, &( mc_26_3_bamboo_pressure_plate_properties ){0}) == 0, "minecraft:bamboo_pressure_plate: accepted state above range");
    mc_26_3_bamboo_pressure_plate_properties invalid = {0};
    invalid.powered = 2;
    CHECK(mc_26_3_bamboo_pressure_plate_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:bamboo_pressure_plate: accepted invalid property value");
}

