static void test_bell(void)
{
    const size_t count = sizeof(test_bell_cases) / sizeof(test_bell_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_bell_case *expected = &test_bell_cases[i];
        mc_26_3_bell_properties actual = {0};
        block_state_id state = mc_26_3_bell_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:bell: properties -> state mismatch");
        b8 ok = mc_26_3_bell_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:bell: get_properties rejected valid state");
        CHECK(actual.attachment == expected->properties.attachment, "minecraft:bell: reverse property mismatch: attachment");
        CHECK(actual.facing == expected->properties.facing, "minecraft:bell: reverse property mismatch: facing");
        CHECK(actual.powered == expected->properties.powered, "minecraft:bell: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_bell_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:bell: get_state(NULL)");
    CHECK(mc_26_3_bell_get_properties(0, NULL) == 0, "minecraft:bell: get_properties(NULL)");
    CHECK(mc_26_3_bell_get_properties(24161, &( mc_26_3_bell_properties ){0}) == 0, "minecraft:bell: accepted state below range");
    CHECK(mc_26_3_bell_get_properties(24194, &( mc_26_3_bell_properties ){0}) == 0, "minecraft:bell: accepted state above range");
    mc_26_3_bell_properties invalid = {0};
    invalid.attachment = (mc_26_3_bell_attachment)-1;
    CHECK(mc_26_3_bell_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:bell: accepted invalid property value");
}

