static void test_blackstone_stairs(void)
{
    const size_t count = sizeof(test_blackstone_stairs_cases) / sizeof(test_blackstone_stairs_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_blackstone_stairs_case *expected = &test_blackstone_stairs_cases[i];
        mc_26_3_blackstone_stairs_properties actual = {0};
        block_state_id state = mc_26_3_blackstone_stairs_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:blackstone_stairs: properties -> state mismatch");
        b8 ok = mc_26_3_blackstone_stairs_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:blackstone_stairs: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:blackstone_stairs: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:blackstone_stairs: reverse property mismatch: half");
        CHECK(actual.shape == expected->properties.shape, "minecraft:blackstone_stairs: reverse property mismatch: shape");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:blackstone_stairs: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_blackstone_stairs_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:blackstone_stairs: get_state(NULL)");
    CHECK(mc_26_3_blackstone_stairs_get_properties(0, NULL) == 0, "minecraft:blackstone_stairs: get_properties(NULL)");
    CHECK(mc_26_3_blackstone_stairs_get_properties(25188, &( mc_26_3_blackstone_stairs_properties ){0}) == 0, "minecraft:blackstone_stairs: accepted state below range");
    CHECK(mc_26_3_blackstone_stairs_get_properties(25269, &( mc_26_3_blackstone_stairs_properties ){0}) == 0, "minecraft:blackstone_stairs: accepted state above range");
    mc_26_3_blackstone_stairs_properties invalid = {0};
    invalid.facing = (mc_26_3_blackstone_stairs_facing)-1;
    CHECK(mc_26_3_blackstone_stairs_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:blackstone_stairs: accepted invalid property value");
}

