static void test_cactus(void)
{
    const size_t count = sizeof(test_cactus_cases) / sizeof(test_cactus_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_cactus_case *expected = &test_cactus_cases[i];
        mc_26_3_cactus_properties actual = {0};
        block_state_id state = mc_26_3_cactus_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:cactus: properties -> state mismatch");
        b8 ok = mc_26_3_cactus_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:cactus: get_properties rejected valid state");
        CHECK(actual.age == expected->properties.age, "minecraft:cactus: reverse property mismatch: age");
    }

    CHECK(mc_26_3_cactus_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:cactus: get_state(NULL)");
    CHECK(mc_26_3_cactus_get_properties(0, NULL) == 0, "minecraft:cactus: get_properties(NULL)");
    CHECK(mc_26_3_cactus_get_properties(8598, &( mc_26_3_cactus_properties ){0}) == 0, "minecraft:cactus: accepted state below range");
    CHECK(mc_26_3_cactus_get_properties(8615, &( mc_26_3_cactus_properties ){0}) == 0, "minecraft:cactus: accepted state above range");
    mc_26_3_cactus_properties invalid = {0};
    invalid.age = (mc_26_3_cactus_age)-1;
    CHECK(mc_26_3_cactus_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:cactus: accepted invalid property value");
}

