static void test_calibrated_sculk_sensor(void)
{
    const size_t count = sizeof(test_calibrated_sculk_sensor_cases) / sizeof(test_calibrated_sculk_sensor_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_calibrated_sculk_sensor_case *expected = &test_calibrated_sculk_sensor_cases[i];
        mc_26_3_calibrated_sculk_sensor_properties actual = {0};
        block_state_id state = mc_26_3_calibrated_sculk_sensor_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:calibrated_sculk_sensor: properties -> state mismatch");
        b8 ok = mc_26_3_calibrated_sculk_sensor_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:calibrated_sculk_sensor: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:calibrated_sculk_sensor: reverse property mismatch: facing");
        CHECK(actual.power == expected->properties.power, "minecraft:calibrated_sculk_sensor: reverse property mismatch: power");
        CHECK(actual.sculk_sensor_phase == expected->properties.sculk_sensor_phase, "minecraft:calibrated_sculk_sensor: reverse property mismatch: sculk_sensor_phase");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:calibrated_sculk_sensor: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_calibrated_sculk_sensor_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:calibrated_sculk_sensor: get_state(NULL)");
    CHECK(mc_26_3_calibrated_sculk_sensor_get_properties(0, NULL) == 0, "minecraft:calibrated_sculk_sensor: get_properties(NULL)");
    CHECK(mc_26_3_calibrated_sculk_sensor_get_properties(30615, &( mc_26_3_calibrated_sculk_sensor_properties ){0}) == 0, "minecraft:calibrated_sculk_sensor: accepted state below range");
    CHECK(mc_26_3_calibrated_sculk_sensor_get_properties(31000, &( mc_26_3_calibrated_sculk_sensor_properties ){0}) == 0, "minecraft:calibrated_sculk_sensor: accepted state above range");
    mc_26_3_calibrated_sculk_sensor_properties invalid = {0};
    invalid.facing = (mc_26_3_calibrated_sculk_sensor_facing)-1;
    CHECK(mc_26_3_calibrated_sculk_sensor_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:calibrated_sculk_sensor: accepted invalid property value");
}

