static void test_chiseled_bookshelf(void)
{
    const size_t count = sizeof(test_chiseled_bookshelf_cases) / sizeof(test_chiseled_bookshelf_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_chiseled_bookshelf_case *expected = &test_chiseled_bookshelf_cases[i];
        mc_26_3_chiseled_bookshelf_properties actual = {0};
        block_state_id state = mc_26_3_chiseled_bookshelf_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:chiseled_bookshelf: properties -> state mismatch");
        b8 ok = mc_26_3_chiseled_bookshelf_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:chiseled_bookshelf: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:chiseled_bookshelf: reverse property mismatch: facing");
        CHECK(actual.slot_0_occupied == expected->properties.slot_0_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_0_occupied");
        CHECK(actual.slot_1_occupied == expected->properties.slot_1_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_1_occupied");
        CHECK(actual.slot_2_occupied == expected->properties.slot_2_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_2_occupied");
        CHECK(actual.slot_3_occupied == expected->properties.slot_3_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_3_occupied");
        CHECK(actual.slot_4_occupied == expected->properties.slot_4_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_4_occupied");
        CHECK(actual.slot_5_occupied == expected->properties.slot_5_occupied, "minecraft:chiseled_bookshelf: reverse property mismatch: slot_5_occupied");
    }

    CHECK(mc_26_3_chiseled_bookshelf_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:chiseled_bookshelf: get_state(NULL)");
    CHECK(mc_26_3_chiseled_bookshelf_get_properties(0, NULL) == 0, "minecraft:chiseled_bookshelf: get_properties(NULL)");
    CHECK(mc_26_3_chiseled_bookshelf_get_properties(3835, &( mc_26_3_chiseled_bookshelf_properties ){0}) == 0, "minecraft:chiseled_bookshelf: accepted state below range");
    CHECK(mc_26_3_chiseled_bookshelf_get_properties(4092, &( mc_26_3_chiseled_bookshelf_properties ){0}) == 0, "minecraft:chiseled_bookshelf: accepted state above range");
    mc_26_3_chiseled_bookshelf_properties invalid = {0};
    invalid.facing = (mc_26_3_chiseled_bookshelf_facing)-1;
    CHECK(mc_26_3_chiseled_bookshelf_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:chiseled_bookshelf: accepted invalid property value");
}

