static void test_copper_chest(void)
{
    const size_t count = sizeof(test_copper_chest_cases) / sizeof(test_copper_chest_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_copper_chest_case *expected = &test_copper_chest_cases[i];
        mc_26_3_copper_chest_properties actual = {0};
        block_state_id state = mc_26_3_copper_chest_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:copper_chest: properties -> state mismatch");
        b8 ok = mc_26_3_copper_chest_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:copper_chest: get_properties rejected valid state");
        CHECK(actual.type == expected->properties.type, "minecraft:copper_chest: reverse property mismatch: type");
        CHECK(actual.facing == expected->properties.facing, "minecraft:copper_chest: reverse property mismatch: facing");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:copper_chest: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_copper_chest_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:copper_chest: get_state(NULL)");
    CHECK(mc_26_3_copper_chest_get_properties(0, NULL) == 0, "minecraft:copper_chest: get_properties(NULL)");
    CHECK(mc_26_3_copper_chest_get_properties(32924, &( mc_26_3_copper_chest_properties ){0}) == 0, "minecraft:copper_chest: accepted state below range");
    CHECK(mc_26_3_copper_chest_get_properties(32949, &( mc_26_3_copper_chest_properties ){0}) == 0, "minecraft:copper_chest: accepted state above range");
    mc_26_3_copper_chest_properties invalid = {0};
    invalid.type = (mc_26_3_copper_chest_type)-1;
    CHECK(mc_26_3_copper_chest_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:copper_chest: accepted invalid property value");
}

