static void test_copper_golem_statue(void)
{
    const size_t count = sizeof(test_copper_golem_statue_cases) / sizeof(test_copper_golem_statue_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_copper_golem_statue_case *expected = &test_copper_golem_statue_cases[i];
        mc_26_3_copper_golem_statue_properties actual = {0};
        block_state_id state = mc_26_3_copper_golem_statue_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:copper_golem_statue: properties -> state mismatch");
        b8 ok = mc_26_3_copper_golem_statue_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:copper_golem_statue: get_properties rejected valid state");
        CHECK(actual.copper_golem_pose == expected->properties.copper_golem_pose, "minecraft:copper_golem_statue: reverse property mismatch: copper_golem_pose");
        CHECK(actual.facing == expected->properties.facing, "minecraft:copper_golem_statue: reverse property mismatch: facing");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:copper_golem_statue: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_copper_golem_statue_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:copper_golem_statue: get_state(NULL)");
    CHECK(mc_26_3_copper_golem_statue_get_properties(0, NULL) == 0, "minecraft:copper_golem_statue: get_properties(NULL)");
    CHECK(mc_26_3_copper_golem_statue_get_properties(33116, &( mc_26_3_copper_golem_statue_properties ){0}) == 0, "minecraft:copper_golem_statue: accepted state below range");
    CHECK(mc_26_3_copper_golem_statue_get_properties(33149, &( mc_26_3_copper_golem_statue_properties ){0}) == 0, "minecraft:copper_golem_statue: accepted state above range");
    mc_26_3_copper_golem_statue_properties invalid = {0};
    invalid.copper_golem_pose = (mc_26_3_copper_golem_statue_copper_golem_pose)-1;
    CHECK(mc_26_3_copper_golem_statue_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:copper_golem_statue: accepted invalid property value");
}

