static void test_crimson_fence(void)
{
    const size_t count = sizeof(test_crimson_fence_cases) / sizeof(test_crimson_fence_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_crimson_fence_case *expected = &test_crimson_fence_cases[i];
        mc_26_3_crimson_fence_properties actual = {0};
        block_state_id state = mc_26_3_crimson_fence_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:crimson_fence: properties -> state mismatch");
        b8 ok = mc_26_3_crimson_fence_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:crimson_fence: get_properties rejected valid state");
        CHECK(actual.east == expected->properties.east, "minecraft:crimson_fence: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:crimson_fence: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:crimson_fence: reverse property mismatch: south");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:crimson_fence: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:crimson_fence: reverse property mismatch: west");
    }

    CHECK(mc_26_3_crimson_fence_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:crimson_fence: get_state(NULL)");
    CHECK(mc_26_3_crimson_fence_get_properties(0, NULL) == 0, "minecraft:crimson_fence: get_properties(NULL)");
    CHECK(mc_26_3_crimson_fence_get_properties(24406, &( mc_26_3_crimson_fence_properties ){0}) == 0, "minecraft:crimson_fence: accepted state below range");
    CHECK(mc_26_3_crimson_fence_get_properties(24439, &( mc_26_3_crimson_fence_properties ){0}) == 0, "minecraft:crimson_fence: accepted state above range");
    mc_26_3_crimson_fence_properties invalid = {0};
    invalid.east = 2;
    CHECK(mc_26_3_crimson_fence_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:crimson_fence: accepted invalid property value");
}

