    CHECK(mc_26_3_crimson_sign_get_properties(25031, &( mc_26_3_crimson_sign_properties ){0}) == 0, "minecraft:crimson_sign: accepted state above range");
    mc_26_3_crimson_sign_properties invalid = {0};
    invalid.rotation = (mc_26_3_crimson_sign_rotation)-1;
