static void test_dark_oak_door(void)
{
    const size_t count = sizeof(test_dark_oak_door_cases) / sizeof(test_dark_oak_door_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_dark_oak_door_case *expected = &test_dark_oak_door_cases[i];
        mc_26_3_dark_oak_door_properties actual = {0};
        block_state_id state = mc_26_3_dark_oak_door_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:dark_oak_door: properties -> state mismatch");
        b8 ok = mc_26_3_dark_oak_door_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:dark_oak_door: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:dark_oak_door: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:dark_oak_door: reverse property mismatch: half");
        CHECK(actual.hinge == expected->properties.hinge, "minecraft:dark_oak_door: reverse property mismatch: hinge");
        CHECK(actual.open == expected->properties.open, "minecraft:dark_oak_door: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:dark_oak_door: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_dark_oak_door_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:dark_oak_door: get_state(NULL)");
    CHECK(mc_26_3_dark_oak_door_get_properties(0, NULL) == 0, "minecraft:dark_oak_door: get_properties(NULL)");
    CHECK(mc_26_3_dark_oak_door_get_properties(16290, &( mc_26_3_dark_oak_door_properties ){0}) == 0, "minecraft:dark_oak_door: accepted state below range");
    CHECK(mc_26_3_dark_oak_door_get_properties(16355, &( mc_26_3_dark_oak_door_properties ){0}) == 0, "minecraft:dark_oak_door: accepted state above range");
    mc_26_3_dark_oak_door_properties invalid = {0};
    invalid.facing = (mc_26_3_dark_oak_door_facing)-1;
    CHECK(mc_26_3_dark_oak_door_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:dark_oak_door: accepted invalid property value");
}

