static void test_dark_oak_leaves(void)
{
    const size_t count = sizeof(test_dark_oak_leaves_cases) / sizeof(test_dark_oak_leaves_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_dark_oak_leaves_case *expected = &test_dark_oak_leaves_cases[i];
        mc_26_3_dark_oak_leaves_properties actual = {0};
        block_state_id state = mc_26_3_dark_oak_leaves_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:dark_oak_leaves: properties -> state mismatch");
        b8 ok = mc_26_3_dark_oak_leaves_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:dark_oak_leaves: get_properties rejected valid state");
        CHECK(actual.distance == expected->properties.distance, "minecraft:dark_oak_leaves: reverse property mismatch: distance");
        CHECK(actual.persistent == expected->properties.persistent, "minecraft:dark_oak_leaves: reverse property mismatch: persistent");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:dark_oak_leaves: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_dark_oak_leaves_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:dark_oak_leaves: get_state(NULL)");
    CHECK(mc_26_3_dark_oak_leaves_get_properties(0, NULL) == 0, "minecraft:dark_oak_leaves: get_properties(NULL)");
    CHECK(mc_26_3_dark_oak_leaves_get_properties(434, &( mc_26_3_dark_oak_leaves_properties ){0}) == 0, "minecraft:dark_oak_leaves: accepted state below range");
    CHECK(mc_26_3_dark_oak_leaves_get_properties(463, &( mc_26_3_dark_oak_leaves_properties ){0}) == 0, "minecraft:dark_oak_leaves: accepted state above range");
    mc_26_3_dark_oak_leaves_properties invalid = {0};
    invalid.distance = (mc_26_3_dark_oak_leaves_distance)-1;
    CHECK(mc_26_3_dark_oak_leaves_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:dark_oak_leaves: accepted invalid property value");
}

