static void test_dispenser(void)
{
    const size_t count = sizeof(test_dispenser_cases) / sizeof(test_dispenser_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_dispenser_case *expected = &test_dispenser_cases[i];
        mc_26_3_dispenser_properties actual = {0};
        block_state_id state = mc_26_3_dispenser_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:dispenser: properties -> state mismatch");
        b8 ok = mc_26_3_dispenser_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:dispenser: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:dispenser: reverse property mismatch: facing");
        CHECK(actual.triggered == expected->properties.triggered, "minecraft:dispenser: reverse property mismatch: triggered");
    }

    CHECK(mc_26_3_dispenser_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:dispenser: get_state(NULL)");
    CHECK(mc_26_3_dispenser_get_properties(0, NULL) == 0, "minecraft:dispenser: get_properties(NULL)");
    CHECK(mc_26_3_dispenser_get_properties(664, &( mc_26_3_dispenser_properties ){0}) == 0, "minecraft:dispenser: accepted state below range");
    CHECK(mc_26_3_dispenser_get_properties(677, &( mc_26_3_dispenser_properties ){0}) == 0, "minecraft:dispenser: accepted state above range");
    mc_26_3_dispenser_properties invalid = {0};
    invalid.facing = (mc_26_3_dispenser_facing)-1;
    CHECK(mc_26_3_dispenser_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:dispenser: accepted invalid property value");
}

