static void test_end_rod(void)
{
    const size_t count = sizeof(test_end_rod_cases) / sizeof(test_end_rod_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_end_rod_case *expected = &test_end_rod_cases[i];
        mc_26_3_end_rod_properties actual = {0};
        block_state_id state = mc_26_3_end_rod_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:end_rod: properties -> state mismatch");
        b8 ok = mc_26_3_end_rod_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:end_rod: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:end_rod: reverse property mismatch: facing");
    }

    CHECK(mc_26_3_end_rod_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:end_rod: get_state(NULL)");
    CHECK(mc_26_3_end_rod_get_properties(0, NULL) == 0, "minecraft:end_rod: get_properties(NULL)");
    CHECK(mc_26_3_end_rod_get_properties(16610, &( mc_26_3_end_rod_properties ){0}) == 0, "minecraft:end_rod: accepted state below range");
    CHECK(mc_26_3_end_rod_get_properties(16617, &( mc_26_3_end_rod_properties ){0}) == 0, "minecraft:end_rod: accepted state above range");
    mc_26_3_end_rod_properties invalid = {0};
    invalid.facing = (mc_26_3_end_rod_facing)-1;
    CHECK(mc_26_3_end_rod_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:end_rod: accepted invalid property value");
}

