    CHECK(mc_26_3_ender_chest_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:ender_chest: get_state(NULL)");
    CHECK(mc_26_3_ender_chest_get_properties(0, NULL) == 0, "minecraft:ender_chest: get_properties(NULL)");
