static void test_exposed_copper_door(void)
{
    const size_t count = sizeof(test_exposed_copper_door_cases) / sizeof(test_exposed_copper_door_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_exposed_copper_door_case *expected = &test_exposed_copper_door_cases[i];
        mc_26_3_exposed_copper_door_properties actual = {0};
        block_state_id state = mc_26_3_exposed_copper_door_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:exposed_copper_door: properties -> state mismatch");
        b8 ok = mc_26_3_exposed_copper_door_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:exposed_copper_door: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:exposed_copper_door: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:exposed_copper_door: reverse property mismatch: half");
        CHECK(actual.hinge == expected->properties.hinge, "minecraft:exposed_copper_door: reverse property mismatch: hinge");
        CHECK(actual.open == expected->properties.open, "minecraft:exposed_copper_door: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:exposed_copper_door: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_exposed_copper_door_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:exposed_copper_door: get_state(NULL)");
    CHECK(mc_26_3_exposed_copper_door_get_properties(0, NULL) == 0, "minecraft:exposed_copper_door: get_properties(NULL)");
    CHECK(mc_26_3_exposed_copper_door_get_properties(31916, &( mc_26_3_exposed_copper_door_properties ){0}) == 0, "minecraft:exposed_copper_door: accepted state below range");
    CHECK(mc_26_3_exposed_copper_door_get_properties(31981, &( mc_26_3_exposed_copper_door_properties ){0}) == 0, "minecraft:exposed_copper_door: accepted state above range");
    mc_26_3_exposed_copper_door_properties invalid = {0};
    invalid.facing = (mc_26_3_exposed_copper_door_facing)-1;
    CHECK(mc_26_3_exposed_copper_door_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:exposed_copper_door: accepted invalid property value");
}

