static void test_fire(void)
{
    const size_t count = sizeof(test_fire_cases) / sizeof(test_fire_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_fire_case *expected = &test_fire_cases[i];
        mc_26_3_fire_properties actual = {0};
        block_state_id state = mc_26_3_fire_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:fire: properties -> state mismatch");
        b8 ok = mc_26_3_fire_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:fire: get_properties rejected valid state");
        CHECK(actual.age == expected->properties.age, "minecraft:fire: reverse property mismatch: age");
        CHECK(actual.east == expected->properties.east, "minecraft:fire: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:fire: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:fire: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:fire: reverse property mismatch: up");
        CHECK(actual.west == expected->properties.west, "minecraft:fire: reverse property mismatch: west");
    }

    CHECK(mc_26_3_fire_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:fire: get_state(NULL)");
    CHECK(mc_26_3_fire_get_properties(0, NULL) == 0, "minecraft:fire: get_properties(NULL)");
    CHECK(mc_26_3_fire_get_properties(4930, &( mc_26_3_fire_properties ){0}) == 0, "minecraft:fire: accepted state below range");
    CHECK(mc_26_3_fire_get_properties(5443, &( mc_26_3_fire_properties ){0}) == 0, "minecraft:fire: accepted state above range");
    mc_26_3_fire_properties invalid = {0};
    invalid.age = (mc_26_3_fire_age)-1;
    CHECK(mc_26_3_fire_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:fire: accepted invalid property value");
}

