static void test_glow_lichen(void)
{
    const size_t count = sizeof(test_glow_lichen_cases) / sizeof(test_glow_lichen_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_glow_lichen_case *expected = &test_glow_lichen_cases[i];
        mc_26_3_glow_lichen_properties actual = {0};
        block_state_id state = mc_26_3_glow_lichen_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:glow_lichen: properties -> state mismatch");
        b8 ok = mc_26_3_glow_lichen_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:glow_lichen: get_properties rejected valid state");
        CHECK(actual.down == expected->properties.down, "minecraft:glow_lichen: reverse property mismatch: down");
        CHECK(actual.east == expected->properties.east, "minecraft:glow_lichen: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:glow_lichen: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:glow_lichen: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:glow_lichen: reverse property mismatch: up");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:glow_lichen: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:glow_lichen: reverse property mismatch: west");
    }

    CHECK(mc_26_3_glow_lichen_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:glow_lichen: get_state(NULL)");
    CHECK(mc_26_3_glow_lichen_get_properties(0, NULL) == 0, "minecraft:glow_lichen: get_properties(NULL)");
    CHECK(mc_26_3_glow_lichen_get_properties(10123, &( mc_26_3_glow_lichen_properties ){0}) == 0, "minecraft:glow_lichen: accepted state below range");
    CHECK(mc_26_3_glow_lichen_get_properties(10252, &( mc_26_3_glow_lichen_properties ){0}) == 0, "minecraft:glow_lichen: accepted state above range");
    mc_26_3_glow_lichen_properties invalid = {0};
    invalid.down = 2;
    CHECK(mc_26_3_glow_lichen_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:glow_lichen: accepted invalid property value");
}

