static void test_granite_stairs(void)
{
    const size_t count = sizeof(test_granite_stairs_cases) / sizeof(test_granite_stairs_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_granite_stairs_case *expected = &test_granite_stairs_cases[i];
        mc_26_3_granite_stairs_properties actual = {0};
        block_state_id state = mc_26_3_granite_stairs_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:granite_stairs: properties -> state mismatch");
        b8 ok = mc_26_3_granite_stairs_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:granite_stairs: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:granite_stairs: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:granite_stairs: reverse property mismatch: half");
        CHECK(actual.shape == expected->properties.shape, "minecraft:granite_stairs: reverse property mismatch: shape");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:granite_stairs: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_granite_stairs_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:granite_stairs: get_state(NULL)");
    CHECK(mc_26_3_granite_stairs_get_properties(0, NULL) == 0, "minecraft:granite_stairs: get_properties(NULL)");
    CHECK(mc_26_3_granite_stairs_get_properties(19372, &( mc_26_3_granite_stairs_properties ){0}) == 0, "minecraft:granite_stairs: accepted state below range");
    CHECK(mc_26_3_granite_stairs_get_properties(19453, &( mc_26_3_granite_stairs_properties ){0}) == 0, "minecraft:granite_stairs: accepted state above range");
    mc_26_3_granite_stairs_properties invalid = {0};
    invalid.facing = (mc_26_3_granite_stairs_facing)-1;
    CHECK(mc_26_3_granite_stairs_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:granite_stairs: accepted invalid property value");
}

