static void test_jungle_trapdoor(void)
{
    const size_t count = sizeof(test_jungle_trapdoor_cases) / sizeof(test_jungle_trapdoor_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_jungle_trapdoor_case *expected = &test_jungle_trapdoor_cases[i];
        mc_26_3_jungle_trapdoor_properties actual = {0};
        block_state_id state = mc_26_3_jungle_trapdoor_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:jungle_trapdoor: properties -> state mismatch");
        b8 ok = mc_26_3_jungle_trapdoor_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:jungle_trapdoor: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:jungle_trapdoor: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:jungle_trapdoor: reverse property mismatch: half");
        CHECK(actual.open == expected->properties.open, "minecraft:jungle_trapdoor: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:jungle_trapdoor: reverse property mismatch: powered");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:jungle_trapdoor: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_jungle_trapdoor_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:jungle_trapdoor: get_state(NULL)");
    CHECK(mc_26_3_jungle_trapdoor_get_properties(0, NULL) == 0, "minecraft:jungle_trapdoor: get_properties(NULL)");
    CHECK(mc_26_3_jungle_trapdoor_get_properties(8975, &( mc_26_3_jungle_trapdoor_properties ){0}) == 0, "minecraft:jungle_trapdoor: accepted state below range");
    CHECK(mc_26_3_jungle_trapdoor_get_properties(9040, &( mc_26_3_jungle_trapdoor_properties ){0}) == 0, "minecraft:jungle_trapdoor: accepted state above range");
    mc_26_3_jungle_trapdoor_properties invalid = {0};
    invalid.facing = (mc_26_3_jungle_trapdoor_facing)-1;
    CHECK(mc_26_3_jungle_trapdoor_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:jungle_trapdoor: accepted invalid property value");
}

