static void test_mangrove_fence(void)
{
    const size_t count = sizeof(test_mangrove_fence_cases) / sizeof(test_mangrove_fence_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_mangrove_fence_case *expected = &test_mangrove_fence_cases[i];
        mc_26_3_mangrove_fence_properties actual = {0};
        block_state_id state = mc_26_3_mangrove_fence_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:mangrove_fence: properties -> state mismatch");
        b8 ok = mc_26_3_mangrove_fence_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:mangrove_fence: get_properties rejected valid state");
        CHECK(actual.east == expected->properties.east, "minecraft:mangrove_fence: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:mangrove_fence: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:mangrove_fence: reverse property mismatch: south");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:mangrove_fence: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:mangrove_fence: reverse property mismatch: west");
    }

    CHECK(mc_26_3_mangrove_fence_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:mangrove_fence: get_state(NULL)");
    CHECK(mc_26_3_mangrove_fence_get_properties(0, NULL) == 0, "minecraft:mangrove_fence: get_properties(NULL)");
    CHECK(mc_26_3_mangrove_fence_get_properties(15874, &( mc_26_3_mangrove_fence_properties ){0}) == 0, "minecraft:mangrove_fence: accepted state below range");
    CHECK(mc_26_3_mangrove_fence_get_properties(15907, &( mc_26_3_mangrove_fence_properties ){0}) == 0, "minecraft:mangrove_fence: accepted state above range");
    mc_26_3_mangrove_fence_properties invalid = {0};
    invalid.east = 2;
    CHECK(mc_26_3_mangrove_fence_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:mangrove_fence: accepted invalid property value");
}

