static void test_mangrove_fence_gate(void)
{
    const size_t count = sizeof(test_mangrove_fence_gate_cases) / sizeof(test_mangrove_fence_gate_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_mangrove_fence_gate_case *expected = &test_mangrove_fence_gate_cases[i];
        mc_26_3_mangrove_fence_gate_properties actual = {0};
        block_state_id state = mc_26_3_mangrove_fence_gate_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:mangrove_fence_gate: properties -> state mismatch");
        b8 ok = mc_26_3_mangrove_fence_gate_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:mangrove_fence_gate: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:mangrove_fence_gate: reverse property mismatch: facing");
        CHECK(actual.in_wall == expected->properties.in_wall, "minecraft:mangrove_fence_gate: reverse property mismatch: in_wall");
        CHECK(actual.open == expected->properties.open, "minecraft:mangrove_fence_gate: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:mangrove_fence_gate: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_mangrove_fence_gate_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:mangrove_fence_gate: get_state(NULL)");
    CHECK(mc_26_3_mangrove_fence_gate_get_properties(0, NULL) == 0, "minecraft:mangrove_fence_gate: get_properties(NULL)");
    CHECK(mc_26_3_mangrove_fence_gate_get_properties(15554, &( mc_26_3_mangrove_fence_gate_properties ){0}) == 0, "minecraft:mangrove_fence_gate: accepted state below range");
    CHECK(mc_26_3_mangrove_fence_gate_get_properties(15587, &( mc_26_3_mangrove_fence_gate_properties ){0}) == 0, "minecraft:mangrove_fence_gate: accepted state above range");
    mc_26_3_mangrove_fence_gate_properties invalid = {0};
    invalid.facing = (mc_26_3_mangrove_fence_gate_facing)-1;
    CHECK(mc_26_3_mangrove_fence_gate_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:mangrove_fence_gate: accepted invalid property value");
}

