static void test_mushroom_stem(void)
{
    const size_t count = sizeof(test_mushroom_stem_cases) / sizeof(test_mushroom_stem_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_mushroom_stem_case *expected = &test_mushroom_stem_cases[i];
        mc_26_3_mushroom_stem_properties actual = {0};
        block_state_id state = mc_26_3_mushroom_stem_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:mushroom_stem: properties -> state mismatch");
        b8 ok = mc_26_3_mushroom_stem_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:mushroom_stem: get_properties rejected valid state");
        CHECK(actual.down == expected->properties.down, "minecraft:mushroom_stem: reverse property mismatch: down");
        CHECK(actual.east == expected->properties.east, "minecraft:mushroom_stem: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:mushroom_stem: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:mushroom_stem: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:mushroom_stem: reverse property mismatch: up");
        CHECK(actual.west == expected->properties.west, "minecraft:mushroom_stem: reverse property mismatch: west");
    }

    CHECK(mc_26_3_mushroom_stem_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:mushroom_stem: get_state(NULL)");
    CHECK(mc_26_3_mushroom_stem_get_properties(0, NULL) == 0, "minecraft:mushroom_stem: get_properties(NULL)");
    CHECK(mc_26_3_mushroom_stem_get_properties(9627, &( mc_26_3_mushroom_stem_properties ){0}) == 0, "minecraft:mushroom_stem: accepted state below range");
    CHECK(mc_26_3_mushroom_stem_get_properties(9692, &( mc_26_3_mushroom_stem_properties ){0}) == 0, "minecraft:mushroom_stem: accepted state above range");
    mc_26_3_mushroom_stem_properties invalid = {0};
    invalid.down = 2;
    CHECK(mc_26_3_mushroom_stem_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:mushroom_stem: accepted invalid property value");
}

