static void test_nether_brick_wall(void)
{
    const size_t count = sizeof(test_nether_brick_wall_cases) / sizeof(test_nether_brick_wall_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_nether_brick_wall_case *expected = &test_nether_brick_wall_cases[i];
        mc_26_3_nether_brick_wall_properties actual = {0};
        block_state_id state = mc_26_3_nether_brick_wall_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:nether_brick_wall: properties -> state mismatch");
        b8 ok = mc_26_3_nether_brick_wall_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:nether_brick_wall: get_properties rejected valid state");
        CHECK(actual.east == expected->properties.east, "minecraft:nether_brick_wall: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:nether_brick_wall: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:nether_brick_wall: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:nether_brick_wall: reverse property mismatch: up");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:nether_brick_wall: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:nether_brick_wall: reverse property mismatch: west");
    }

    CHECK(mc_26_3_nether_brick_wall_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:nether_brick_wall: get_state(NULL)");
    CHECK(mc_26_3_nether_brick_wall_get_properties(0, NULL) == 0, "minecraft:nether_brick_wall: get_properties(NULL)");
    CHECK(mc_26_3_nether_brick_wall_get_properties(22118, &( mc_26_3_nether_brick_wall_properties ){0}) == 0, "minecraft:nether_brick_wall: accepted state below range");
    CHECK(mc_26_3_nether_brick_wall_get_properties(22443, &( mc_26_3_nether_brick_wall_properties ){0}) == 0, "minecraft:nether_brick_wall: accepted state above range");
    mc_26_3_nether_brick_wall_properties invalid = {0};
    invalid.east = (mc_26_3_nether_brick_wall_east)-1;
    CHECK(mc_26_3_nether_brick_wall_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:nether_brick_wall: accepted invalid property value");
}

