static void test_note_block(void)
{
    const size_t count = sizeof(test_note_block_cases) / sizeof(test_note_block_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_note_block_case *expected = &test_note_block_cases[i];
        mc_26_3_note_block_properties actual = {0};
        block_state_id state = mc_26_3_note_block_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:note_block: properties -> state mismatch");
        b8 ok = mc_26_3_note_block_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:note_block: get_properties rejected valid state");
        CHECK(actual.instrument == expected->properties.instrument, "minecraft:note_block: reverse property mismatch: instrument");
        CHECK(actual.note == expected->properties.note, "minecraft:note_block: reverse property mismatch: note");
        CHECK(actual.powered == expected->properties.powered, "minecraft:note_block: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_note_block_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:note_block: get_state(NULL)");
    CHECK(mc_26_3_note_block_get_properties(0, NULL) == 0, "minecraft:note_block: get_properties(NULL)");
    CHECK(mc_26_3_note_block_get_properties(679, &( mc_26_3_note_block_properties ){0}) == 0, "minecraft:note_block: accepted state below range");
    CHECK(mc_26_3_note_block_get_properties(2030, &( mc_26_3_note_block_properties ){0}) == 0, "minecraft:note_block: accepted state above range");
    mc_26_3_note_block_properties invalid = {0};
    invalid.instrument = (mc_26_3_note_block_instrument)-1;
    CHECK(mc_26_3_note_block_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:note_block: accepted invalid property value");
}

