static void test_oak_button(void)
{
    const size_t count = sizeof(test_oak_button_cases) / sizeof(test_oak_button_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_oak_button_case *expected = &test_oak_button_cases[i];
        mc_26_3_oak_button_properties actual = {0};
        block_state_id state = mc_26_3_oak_button_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:oak_button: properties -> state mismatch");
        b8 ok = mc_26_3_oak_button_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:oak_button: get_properties rejected valid state");
        CHECK(actual.face == expected->properties.face, "minecraft:oak_button: reverse property mismatch: face");
        CHECK(actual.facing == expected->properties.facing, "minecraft:oak_button: reverse property mismatch: facing");
        CHECK(actual.powered == expected->properties.powered, "minecraft:oak_button: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_oak_button_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:oak_button: get_state(NULL)");
    CHECK(mc_26_3_oak_button_get_properties(0, NULL) == 0, "minecraft:oak_button: get_properties(NULL)");
    CHECK(mc_26_3_oak_button_get_properties(12417, &( mc_26_3_oak_button_properties ){0}) == 0, "minecraft:oak_button: accepted state below range");
    CHECK(mc_26_3_oak_button_get_properties(12442, &( mc_26_3_oak_button_properties ){0}) == 0, "minecraft:oak_button: accepted state above range");
    mc_26_3_oak_button_properties invalid = {0};
    invalid.face = (mc_26_3_oak_button_face)-1;
    CHECK(mc_26_3_oak_button_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:oak_button: accepted invalid property value");
}

