static void test_pale_moss_carpet(void)
{
    const size_t count = sizeof(test_pale_moss_carpet_cases) / sizeof(test_pale_moss_carpet_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_pale_moss_carpet_case *expected = &test_pale_moss_carpet_cases[i];
        mc_26_3_pale_moss_carpet_properties actual = {0};
        block_state_id state = mc_26_3_pale_moss_carpet_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:pale_moss_carpet: properties -> state mismatch");
        b8 ok = mc_26_3_pale_moss_carpet_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:pale_moss_carpet: get_properties rejected valid state");
        CHECK(actual.bottom == expected->properties.bottom, "minecraft:pale_moss_carpet: reverse property mismatch: bottom");
        CHECK(actual.east == expected->properties.east, "minecraft:pale_moss_carpet: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:pale_moss_carpet: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:pale_moss_carpet: reverse property mismatch: south");
        CHECK(actual.west == expected->properties.west, "minecraft:pale_moss_carpet: reverse property mismatch: west");
    }

    CHECK(mc_26_3_pale_moss_carpet_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:pale_moss_carpet: get_state(NULL)");
    CHECK(mc_26_3_pale_moss_carpet_get_properties(0, NULL) == 0, "minecraft:pale_moss_carpet: get_properties(NULL)");
    CHECK(mc_26_3_pale_moss_carpet_get_properties(35553, &( mc_26_3_pale_moss_carpet_properties ){0}) == 0, "minecraft:pale_moss_carpet: accepted state below range");
    CHECK(mc_26_3_pale_moss_carpet_get_properties(35716, &( mc_26_3_pale_moss_carpet_properties ){0}) == 0, "minecraft:pale_moss_carpet: accepted state above range");
    mc_26_3_pale_moss_carpet_properties invalid = {0};
    invalid.bottom = 2;
    CHECK(mc_26_3_pale_moss_carpet_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:pale_moss_carpet: accepted invalid property value");
}

