static void test_poplar_hanging_sign(void)
{
    const size_t count = sizeof(test_poplar_hanging_sign_cases) / sizeof(test_poplar_hanging_sign_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_poplar_hanging_sign_case *expected = &test_poplar_hanging_sign_cases[i];
        mc_26_3_poplar_hanging_sign_properties actual = {0};
        block_state_id state = mc_26_3_poplar_hanging_sign_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:poplar_hanging_sign: properties -> state mismatch");
        b8 ok = mc_26_3_poplar_hanging_sign_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:poplar_hanging_sign: get_properties rejected valid state");
        CHECK(actual.attached == expected->properties.attached, "minecraft:poplar_hanging_sign: reverse property mismatch: attached");
        CHECK(actual.rotation == expected->properties.rotation, "minecraft:poplar_hanging_sign: reverse property mismatch: rotation");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:poplar_hanging_sign: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_poplar_hanging_sign_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:poplar_hanging_sign: get_state(NULL)");
    CHECK(mc_26_3_poplar_hanging_sign_get_properties(0, NULL) == 0, "minecraft:poplar_hanging_sign: get_properties(NULL)");
    CHECK(mc_26_3_poplar_hanging_sign_get_properties(8206, &( mc_26_3_poplar_hanging_sign_properties ){0}) == 0, "minecraft:poplar_hanging_sign: accepted state below range");
    CHECK(mc_26_3_poplar_hanging_sign_get_properties(8271, &( mc_26_3_poplar_hanging_sign_properties ){0}) == 0, "minecraft:poplar_hanging_sign: accepted state above range");
    mc_26_3_poplar_hanging_sign_properties invalid = {0};
    invalid.attached = 2;
    CHECK(mc_26_3_poplar_hanging_sign_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:poplar_hanging_sign: accepted invalid property value");
}

