static void test_purple_bed(void)
{
    const size_t count = sizeof(test_purple_bed_cases) / sizeof(test_purple_bed_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_purple_bed_case *expected = &test_purple_bed_cases[i];
        mc_26_3_purple_bed_properties actual = {0};
        block_state_id state = mc_26_3_purple_bed_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:purple_bed: properties -> state mismatch");
        b8 ok = mc_26_3_purple_bed_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:purple_bed: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:purple_bed: reverse property mismatch: facing");
        CHECK(actual.occupied == expected->properties.occupied, "minecraft:purple_bed: reverse property mismatch: occupied");
        CHECK(actual.part == expected->properties.part, "minecraft:purple_bed: reverse property mismatch: part");
    }

    CHECK(mc_26_3_purple_bed_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:purple_bed: get_state(NULL)");
    CHECK(mc_26_3_purple_bed_get_properties(0, NULL) == 0, "minecraft:purple_bed: get_properties(NULL)");
    CHECK(mc_26_3_purple_bed_get_properties(2189, &( mc_26_3_purple_bed_properties ){0}) == 0, "minecraft:purple_bed: accepted state below range");
    CHECK(mc_26_3_purple_bed_get_properties(2206, &( mc_26_3_purple_bed_properties ){0}) == 0, "minecraft:purple_bed: accepted state above range");
    mc_26_3_purple_bed_properties invalid = {0};
    invalid.facing = (mc_26_3_purple_bed_facing)-1;
    CHECK(mc_26_3_purple_bed_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:purple_bed: accepted invalid property value");
}

