static void test_purple_stained_glass_pane(void)
{
    const size_t count = sizeof(test_purple_stained_glass_pane_cases) / sizeof(test_purple_stained_glass_pane_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_purple_stained_glass_pane_case *expected = &test_purple_stained_glass_pane_cases[i];
        mc_26_3_purple_stained_glass_pane_properties actual = {0};
        block_state_id state = mc_26_3_purple_stained_glass_pane_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:purple_stained_glass_pane: properties -> state mismatch");
        b8 ok = mc_26_3_purple_stained_glass_pane_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:purple_stained_glass_pane: get_properties rejected valid state");
        CHECK(actual.east == expected->properties.east, "minecraft:purple_stained_glass_pane: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:purple_stained_glass_pane: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:purple_stained_glass_pane: reverse property mismatch: south");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:purple_stained_glass_pane: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:purple_stained_glass_pane: reverse property mismatch: west");
    }

    CHECK(mc_26_3_purple_stained_glass_pane_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:purple_stained_glass_pane: get_state(NULL)");
    CHECK(mc_26_3_purple_stained_glass_pane_get_properties(0, NULL) == 0, "minecraft:purple_stained_glass_pane: get_properties(NULL)");
    CHECK(mc_26_3_purple_stained_glass_pane_get_properties(13546, &( mc_26_3_purple_stained_glass_pane_properties ){0}) == 0, "minecraft:purple_stained_glass_pane: accepted state below range");
    CHECK(mc_26_3_purple_stained_glass_pane_get_properties(13579, &( mc_26_3_purple_stained_glass_pane_properties ){0}) == 0, "minecraft:purple_stained_glass_pane: accepted state above range");
    mc_26_3_purple_stained_glass_pane_properties invalid = {0};
    invalid.east = 2;
    CHECK(mc_26_3_purple_stained_glass_pane_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:purple_stained_glass_pane: accepted invalid property value");
}

