static void test_red_mushroom_block(void)
{
    const size_t count = sizeof(test_red_mushroom_block_cases) / sizeof(test_red_mushroom_block_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_red_mushroom_block_case *expected = &test_red_mushroom_block_cases[i];
        mc_26_3_red_mushroom_block_properties actual = {0};
        block_state_id state = mc_26_3_red_mushroom_block_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:red_mushroom_block: properties -> state mismatch");
        b8 ok = mc_26_3_red_mushroom_block_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:red_mushroom_block: get_properties rejected valid state");
        CHECK(actual.down == expected->properties.down, "minecraft:red_mushroom_block: reverse property mismatch: down");
        CHECK(actual.east == expected->properties.east, "minecraft:red_mushroom_block: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:red_mushroom_block: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:red_mushroom_block: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:red_mushroom_block: reverse property mismatch: up");
        CHECK(actual.west == expected->properties.west, "minecraft:red_mushroom_block: reverse property mismatch: west");
    }

    CHECK(mc_26_3_red_mushroom_block_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:red_mushroom_block: get_state(NULL)");
    CHECK(mc_26_3_red_mushroom_block_get_properties(0, NULL) == 0, "minecraft:red_mushroom_block: get_properties(NULL)");
    CHECK(mc_26_3_red_mushroom_block_get_properties(9563, &( mc_26_3_red_mushroom_block_properties ){0}) == 0, "minecraft:red_mushroom_block: accepted state below range");
    CHECK(mc_26_3_red_mushroom_block_get_properties(9628, &( mc_26_3_red_mushroom_block_properties ){0}) == 0, "minecraft:red_mushroom_block: accepted state above range");
    mc_26_3_red_mushroom_block_properties invalid = {0};
    invalid.down = 2;
    CHECK(mc_26_3_red_mushroom_block_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:red_mushroom_block: accepted invalid property value");
}

