static void test_redstone_wire(void)
{
    const size_t count = sizeof(test_redstone_wire_cases) / sizeof(test_redstone_wire_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_redstone_wire_case *expected = &test_redstone_wire_cases[i];
        mc_26_3_redstone_wire_properties actual = {0};
        block_state_id state = mc_26_3_redstone_wire_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:redstone_wire: properties -> state mismatch");
        b8 ok = mc_26_3_redstone_wire_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:redstone_wire: get_properties rejected valid state");
        CHECK(actual.east == expected->properties.east, "minecraft:redstone_wire: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:redstone_wire: reverse property mismatch: north");
        CHECK(actual.power == expected->properties.power, "minecraft:redstone_wire: reverse property mismatch: power");
        CHECK(actual.south == expected->properties.south, "minecraft:redstone_wire: reverse property mismatch: south");
        CHECK(actual.west == expected->properties.west, "minecraft:redstone_wire: reverse property mismatch: west");
    }

    CHECK(mc_26_3_redstone_wire_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:redstone_wire: get_state(NULL)");
    CHECK(mc_26_3_redstone_wire_get_properties(0, NULL) == 0, "minecraft:redstone_wire: get_properties(NULL)");
    CHECK(mc_26_3_redstone_wire_get_properties(5566, &( mc_26_3_redstone_wire_properties ){0}) == 0, "minecraft:redstone_wire: accepted state below range");
    CHECK(mc_26_3_redstone_wire_get_properties(6863, &( mc_26_3_redstone_wire_properties ){0}) == 0, "minecraft:redstone_wire: accepted state above range");
    mc_26_3_redstone_wire_properties invalid = {0};
    invalid.east = (mc_26_3_redstone_wire_east)-1;
    CHECK(mc_26_3_redstone_wire_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:redstone_wire: accepted invalid property value");
}

