static void test_repeating_command_block(void)
{
    const size_t count = sizeof(test_repeating_command_block_cases) / sizeof(test_repeating_command_block_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_repeating_command_block_case *expected = &test_repeating_command_block_cases[i];
        mc_26_3_repeating_command_block_properties actual = {0};
        block_state_id state = mc_26_3_repeating_command_block_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:repeating_command_block: properties -> state mismatch");
        b8 ok = mc_26_3_repeating_command_block_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:repeating_command_block: get_properties rejected valid state");
        CHECK(actual.conditional == expected->properties.conditional, "minecraft:repeating_command_block: reverse property mismatch: conditional");
        CHECK(actual.facing == expected->properties.facing, "minecraft:repeating_command_block: reverse property mismatch: facing");
    }

    CHECK(mc_26_3_repeating_command_block_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:repeating_command_block: get_state(NULL)");
    CHECK(mc_26_3_repeating_command_block_get_properties(0, NULL) == 0, "minecraft:repeating_command_block: get_properties(NULL)");
    CHECK(mc_26_3_repeating_command_block_get_properties(16797, &( mc_26_3_repeating_command_block_properties ){0}) == 0, "minecraft:repeating_command_block: accepted state below range");
    CHECK(mc_26_3_repeating_command_block_get_properties(16810, &( mc_26_3_repeating_command_block_properties ){0}) == 0, "minecraft:repeating_command_block: accepted state above range");
    mc_26_3_repeating_command_block_properties invalid = {0};
    invalid.conditional = 2;
    CHECK(mc_26_3_repeating_command_block_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:repeating_command_block: accepted invalid property value");
}

