static void test_resin_clump(void)
{
    const size_t count = sizeof(test_resin_clump_cases) / sizeof(test_resin_clump_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_resin_clump_case *expected = &test_resin_clump_cases[i];
        mc_26_3_resin_clump_properties actual = {0};
        block_state_id state = mc_26_3_resin_clump_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:resin_clump: properties -> state mismatch");
        b8 ok = mc_26_3_resin_clump_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:resin_clump: get_properties rejected valid state");
        CHECK(actual.down == expected->properties.down, "minecraft:resin_clump: reverse property mismatch: down");
        CHECK(actual.east == expected->properties.east, "minecraft:resin_clump: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:resin_clump: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:resin_clump: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:resin_clump: reverse property mismatch: up");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:resin_clump: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:resin_clump: reverse property mismatch: west");
    }

    CHECK(mc_26_3_resin_clump_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:resin_clump: get_state(NULL)");
    CHECK(mc_26_3_resin_clump_get_properties(0, NULL) == 0, "minecraft:resin_clump: get_properties(NULL)");
    CHECK(mc_26_3_resin_clump_get_properties(10251, &( mc_26_3_resin_clump_properties ){0}) == 0, "minecraft:resin_clump: accepted state below range");
    CHECK(mc_26_3_resin_clump_get_properties(10380, &( mc_26_3_resin_clump_properties ){0}) == 0, "minecraft:resin_clump: accepted state above range");
    mc_26_3_resin_clump_properties invalid = {0};
    invalid.down = 2;
    CHECK(mc_26_3_resin_clump_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:resin_clump: accepted invalid property value");
}

