static void test_scaffolding(void)
{
    const size_t count = sizeof(test_scaffolding_cases) / sizeof(test_scaffolding_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_scaffolding_case *expected = &test_scaffolding_cases[i];
        mc_26_3_scaffolding_properties actual = {0};
        block_state_id state = mc_26_3_scaffolding_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:scaffolding: properties -> state mismatch");
        b8 ok = mc_26_3_scaffolding_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:scaffolding: get_properties rejected valid state");
        CHECK(actual.bottom == expected->properties.bottom, "minecraft:scaffolding: reverse property mismatch: bottom");
        CHECK(actual.distance == expected->properties.distance, "minecraft:scaffolding: reverse property mismatch: distance");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:scaffolding: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_scaffolding_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:scaffolding: get_state(NULL)");
    CHECK(mc_26_3_scaffolding_get_properties(0, NULL) == 0, "minecraft:scaffolding: get_properties(NULL)");
    CHECK(mc_26_3_scaffolding_get_properties(24062, &( mc_26_3_scaffolding_properties ){0}) == 0, "minecraft:scaffolding: accepted state below range");
    CHECK(mc_26_3_scaffolding_get_properties(24095, &( mc_26_3_scaffolding_properties ){0}) == 0, "minecraft:scaffolding: accepted state above range");
    mc_26_3_scaffolding_properties invalid = {0};
    invalid.bottom = 2;
    CHECK(mc_26_3_scaffolding_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:scaffolding: accepted invalid property value");
}

