static void test_sculk_vein(void)
{
    const size_t count = sizeof(test_sculk_vein_cases) / sizeof(test_sculk_vein_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_sculk_vein_case *expected = &test_sculk_vein_cases[i];
        mc_26_3_sculk_vein_properties actual = {0};
        block_state_id state = mc_26_3_sculk_vein_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:sculk_vein: properties -> state mismatch");
        b8 ok = mc_26_3_sculk_vein_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:sculk_vein: get_properties rejected valid state");
        CHECK(actual.down == expected->properties.down, "minecraft:sculk_vein: reverse property mismatch: down");
        CHECK(actual.east == expected->properties.east, "minecraft:sculk_vein: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:sculk_vein: reverse property mismatch: north");
        CHECK(actual.south == expected->properties.south, "minecraft:sculk_vein: reverse property mismatch: south");
        CHECK(actual.up == expected->properties.up, "minecraft:sculk_vein: reverse property mismatch: up");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:sculk_vein: reverse property mismatch: waterlogged");
        CHECK(actual.west == expected->properties.west, "minecraft:sculk_vein: reverse property mismatch: west");
    }

    CHECK(mc_26_3_sculk_vein_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:sculk_vein: get_state(NULL)");
    CHECK(mc_26_3_sculk_vein_get_properties(0, NULL) == 0, "minecraft:sculk_vein: get_properties(NULL)");
    CHECK(mc_26_3_sculk_vein_get_properties(31000, &( mc_26_3_sculk_vein_properties ){0}) == 0, "minecraft:sculk_vein: accepted state below range");
    CHECK(mc_26_3_sculk_vein_get_properties(31129, &( mc_26_3_sculk_vein_properties ){0}) == 0, "minecraft:sculk_vein: accepted state above range");
    mc_26_3_sculk_vein_properties invalid = {0};
    invalid.down = 2;
    CHECK(mc_26_3_sculk_vein_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:sculk_vein: accepted invalid property value");
}

