        mc_26_3_spruce_shelf_properties actual = {0};
        block_state_id state = mc_26_3_spruce_shelf_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:spruce_shelf: properties -> state mismatch");
        b8 ok = mc_26_3_spruce_shelf_get_properties(expected->state, &actual);
