static void test_tripwire(void)
{
    const size_t count = sizeof(test_tripwire_cases) / sizeof(test_tripwire_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_tripwire_case *expected = &test_tripwire_cases[i];
        mc_26_3_tripwire_properties actual = {0};
        block_state_id state = mc_26_3_tripwire_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:tripwire: properties -> state mismatch");
        b8 ok = mc_26_3_tripwire_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:tripwire: get_properties rejected valid state");
        CHECK(actual.attached == expected->properties.attached, "minecraft:tripwire: reverse property mismatch: attached");
        CHECK(actual.disarmed == expected->properties.disarmed, "minecraft:tripwire: reverse property mismatch: disarmed");
        CHECK(actual.east == expected->properties.east, "minecraft:tripwire: reverse property mismatch: east");
        CHECK(actual.north == expected->properties.north, "minecraft:tripwire: reverse property mismatch: north");
        CHECK(actual.powered == expected->properties.powered, "minecraft:tripwire: reverse property mismatch: powered");
        CHECK(actual.south == expected->properties.south, "minecraft:tripwire: reverse property mismatch: south");
        CHECK(actual.west == expected->properties.west, "minecraft:tripwire: reverse property mismatch: west");
    }

    CHECK(mc_26_3_tripwire_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:tripwire: get_state(NULL)");
    CHECK(mc_26_3_tripwire_get_properties(0, NULL) == 0, "minecraft:tripwire: get_properties(NULL)");
    CHECK(mc_26_3_tripwire_get_properties(11340, &( mc_26_3_tripwire_properties ){0}) == 0, "minecraft:tripwire: accepted state below range");
    CHECK(mc_26_3_tripwire_get_properties(11469, &( mc_26_3_tripwire_properties ){0}) == 0, "minecraft:tripwire: accepted state above range");
    mc_26_3_tripwire_properties invalid = {0};
    invalid.attached = 2;
    CHECK(mc_26_3_tripwire_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:tripwire: accepted invalid property value");
}

