static void test_tuff_slab(void)
{
    const size_t count = sizeof(test_tuff_slab_cases) / sizeof(test_tuff_slab_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_tuff_slab_case *expected = &test_tuff_slab_cases[i];
        mc_26_3_tuff_slab_properties actual = {0};
        block_state_id state = mc_26_3_tuff_slab_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:tuff_slab: properties -> state mismatch");
        b8 ok = mc_26_3_tuff_slab_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:tuff_slab: get_properties rejected valid state");
        CHECK(actual.type == expected->properties.type, "minecraft:tuff_slab: reverse property mismatch: type");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:tuff_slab: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_tuff_slab_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:tuff_slab: get_state(NULL)");
    CHECK(mc_26_3_tuff_slab_get_properties(0, NULL) == 0, "minecraft:tuff_slab: get_properties(NULL)");
    CHECK(mc_26_3_tuff_slab_get_properties(26809, &( mc_26_3_tuff_slab_properties ){0}) == 0, "minecraft:tuff_slab: accepted state below range");
    CHECK(mc_26_3_tuff_slab_get_properties(26816, &( mc_26_3_tuff_slab_properties ){0}) == 0, "minecraft:tuff_slab: accepted state above range");
    mc_26_3_tuff_slab_properties invalid = {0};
    invalid.type = (mc_26_3_tuff_slab_type)-1;
    CHECK(mc_26_3_tuff_slab_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:tuff_slab: accepted invalid property value");
}

