static void test_warped_shelf(void)
{
    const size_t count = sizeof(test_warped_shelf_cases) / sizeof(test_warped_shelf_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_warped_shelf_case *expected = &test_warped_shelf_cases[i];
        mc_26_3_warped_shelf_properties actual = {0};
        block_state_id state = mc_26_3_warped_shelf_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:warped_shelf: properties -> state mismatch");
        b8 ok = mc_26_3_warped_shelf_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:warped_shelf: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:warped_shelf: reverse property mismatch: facing");
        CHECK(actual.powered == expected->properties.powered, "minecraft:warped_shelf: reverse property mismatch: powered");
        CHECK(actual.side_chain == expected->properties.side_chain, "minecraft:warped_shelf: reverse property mismatch: side_chain");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:warped_shelf: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_warped_shelf_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:warped_shelf: get_state(NULL)");
    CHECK(mc_26_3_warped_shelf_get_properties(0, NULL) == 0, "minecraft:warped_shelf: get_properties(NULL)");
    CHECK(mc_26_3_warped_shelf_get_properties(4859, &( mc_26_3_warped_shelf_properties ){0}) == 0, "minecraft:warped_shelf: accepted state below range");
    CHECK(mc_26_3_warped_shelf_get_properties(4924, &( mc_26_3_warped_shelf_properties ){0}) == 0, "minecraft:warped_shelf: accepted state above range");
    mc_26_3_warped_shelf_properties invalid = {0};
    invalid.facing = (mc_26_3_warped_shelf_facing)-1;
    CHECK(mc_26_3_warped_shelf_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:warped_shelf: accepted invalid property value");
}

