static void test_waxed_oxidized_copper_door(void)
{
    const size_t count = sizeof(test_waxed_oxidized_copper_door_cases) / sizeof(test_waxed_oxidized_copper_door_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_waxed_oxidized_copper_door_case *expected = &test_waxed_oxidized_copper_door_cases[i];
        mc_26_3_waxed_oxidized_copper_door_properties actual = {0};
        block_state_id state = mc_26_3_waxed_oxidized_copper_door_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:waxed_oxidized_copper_door: properties -> state mismatch");
        b8 ok = mc_26_3_waxed_oxidized_copper_door_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:waxed_oxidized_copper_door: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:waxed_oxidized_copper_door: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:waxed_oxidized_copper_door: reverse property mismatch: half");
        CHECK(actual.hinge == expected->properties.hinge, "minecraft:waxed_oxidized_copper_door: reverse property mismatch: hinge");
        CHECK(actual.open == expected->properties.open, "minecraft:waxed_oxidized_copper_door: reverse property mismatch: open");
        CHECK(actual.powered == expected->properties.powered, "minecraft:waxed_oxidized_copper_door: reverse property mismatch: powered");
    }

    CHECK(mc_26_3_waxed_oxidized_copper_door_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:waxed_oxidized_copper_door: get_state(NULL)");
    CHECK(mc_26_3_waxed_oxidized_copper_door_get_properties(0, NULL) == 0, "minecraft:waxed_oxidized_copper_door: get_properties(NULL)");
    CHECK(mc_26_3_waxed_oxidized_copper_door_get_properties(32300, &( mc_26_3_waxed_oxidized_copper_door_properties ){0}) == 0, "minecraft:waxed_oxidized_copper_door: accepted state below range");
    CHECK(mc_26_3_waxed_oxidized_copper_door_get_properties(32365, &( mc_26_3_waxed_oxidized_copper_door_properties ){0}) == 0, "minecraft:waxed_oxidized_copper_door: accepted state above range");
    mc_26_3_waxed_oxidized_copper_door_properties invalid = {0};
    invalid.facing = (mc_26_3_waxed_oxidized_copper_door_facing)-1;
    CHECK(mc_26_3_waxed_oxidized_copper_door_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:waxed_oxidized_copper_door: accepted invalid property value");
}

