static void test_waxed_oxidized_cut_copper_stairs(void)
{
    const size_t count = sizeof(test_waxed_oxidized_cut_copper_stairs_cases) / sizeof(test_waxed_oxidized_cut_copper_stairs_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_waxed_oxidized_cut_copper_stairs_case *expected = &test_waxed_oxidized_cut_copper_stairs_cases[i];
        mc_26_3_waxed_oxidized_cut_copper_stairs_properties actual = {0};
        block_state_id state = mc_26_3_waxed_oxidized_cut_copper_stairs_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:waxed_oxidized_cut_copper_stairs: properties -> state mismatch");
        b8 ok = mc_26_3_waxed_oxidized_cut_copper_stairs_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:waxed_oxidized_cut_copper_stairs: get_properties rejected valid state");
        CHECK(actual.facing == expected->properties.facing, "minecraft:waxed_oxidized_cut_copper_stairs: reverse property mismatch: facing");
        CHECK(actual.half == expected->properties.half, "minecraft:waxed_oxidized_cut_copper_stairs: reverse property mismatch: half");
        CHECK(actual.shape == expected->properties.shape, "minecraft:waxed_oxidized_cut_copper_stairs: reverse property mismatch: shape");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:waxed_oxidized_cut_copper_stairs: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_waxed_oxidized_cut_copper_stairs_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:waxed_oxidized_cut_copper_stairs: get_state(NULL)");
    CHECK(mc_26_3_waxed_oxidized_cut_copper_stairs_get_properties(0, NULL) == 0, "minecraft:waxed_oxidized_cut_copper_stairs: get_properties(NULL)");
    CHECK(mc_26_3_waxed_oxidized_cut_copper_stairs_get_properties(31724, &( mc_26_3_waxed_oxidized_cut_copper_stairs_properties ){0}) == 0, "minecraft:waxed_oxidized_cut_copper_stairs: accepted state below range");
    CHECK(mc_26_3_waxed_oxidized_cut_copper_stairs_get_properties(31805, &( mc_26_3_waxed_oxidized_cut_copper_stairs_properties ){0}) == 0, "minecraft:waxed_oxidized_cut_copper_stairs: accepted state above range");
    mc_26_3_waxed_oxidized_cut_copper_stairs_properties invalid = {0};
    invalid.facing = (mc_26_3_waxed_oxidized_cut_copper_stairs_facing)-1;
    CHECK(mc_26_3_waxed_oxidized_cut_copper_stairs_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:waxed_oxidized_cut_copper_stairs: accepted invalid property value");
}

