static void test_weathered_copper_chest(void)
{
    const size_t count = sizeof(test_weathered_copper_chest_cases) / sizeof(test_weathered_copper_chest_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_weathered_copper_chest_case *expected = &test_weathered_copper_chest_cases[i];
        mc_26_3_weathered_copper_chest_properties actual = {0};
        block_state_id state = mc_26_3_weathered_copper_chest_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:weathered_copper_chest: properties -> state mismatch");
        b8 ok = mc_26_3_weathered_copper_chest_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:weathered_copper_chest: get_properties rejected valid state");
        CHECK(actual.type == expected->properties.type, "minecraft:weathered_copper_chest: reverse property mismatch: type");
        CHECK(actual.facing == expected->properties.facing, "minecraft:weathered_copper_chest: reverse property mismatch: facing");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:weathered_copper_chest: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_weathered_copper_chest_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:weathered_copper_chest: get_state(NULL)");
    CHECK(mc_26_3_weathered_copper_chest_get_properties(0, NULL) == 0, "minecraft:weathered_copper_chest: get_properties(NULL)");
    CHECK(mc_26_3_weathered_copper_chest_get_properties(32972, &( mc_26_3_weathered_copper_chest_properties ){0}) == 0, "minecraft:weathered_copper_chest: accepted state below range");
    CHECK(mc_26_3_weathered_copper_chest_get_properties(32997, &( mc_26_3_weathered_copper_chest_properties ){0}) == 0, "minecraft:weathered_copper_chest: accepted state above range");
    mc_26_3_weathered_copper_chest_properties invalid = {0};
    invalid.type = (mc_26_3_weathered_copper_chest_type)-1;
    CHECK(mc_26_3_weathered_copper_chest_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:weathered_copper_chest: accepted invalid property value");
}

