static void test_white_candle(void)
{
    const size_t count = sizeof(test_white_candle_cases) / sizeof(test_white_candle_cases[0]);
    for (size_t i = 0; i < count; ++i) {
        const test_white_candle_case *expected = &test_white_candle_cases[i];
        mc_26_3_white_candle_properties actual = {0};
        block_state_id state = mc_26_3_white_candle_get_state(&expected->properties);
        CHECK(state == expected->state, "minecraft:white_candle: properties -> state mismatch");
        b8 ok = mc_26_3_white_candle_get_properties(expected->state, &actual);
        CHECK(ok != 0, "minecraft:white_candle: get_properties rejected valid state");
        CHECK(actual.candles == expected->properties.candles, "minecraft:white_candle: reverse property mismatch: candles");
        CHECK(actual.lit == expected->properties.lit, "minecraft:white_candle: reverse property mismatch: lit");
        CHECK(actual.waterlogged == expected->properties.waterlogged, "minecraft:white_candle: reverse property mismatch: waterlogged");
    }

    CHECK(mc_26_3_white_candle_get_state(NULL) == BLOCK_INVALID_ID, "minecraft:white_candle: get_state(NULL)");
    CHECK(mc_26_3_white_candle_get_properties(0, NULL) == 0, "minecraft:white_candle: get_properties(NULL)");
    CHECK(mc_26_3_white_candle_get_properties(26468, &( mc_26_3_white_candle_properties ){0}) == 0, "minecraft:white_candle: accepted state below range");
    CHECK(mc_26_3_white_candle_get_properties(26485, &( mc_26_3_white_candle_properties ){0}) == 0, "minecraft:white_candle: accepted state above range");
    mc_26_3_white_candle_properties invalid = {0};
    invalid.candles = (mc_26_3_white_candle_candles)-1;
    CHECK(mc_26_3_white_candle_get_state(&invalid) == BLOCK_INVALID_ID, "minecraft:white_candle: accepted invalid property value");
}

